[CmdletBinding()]
param([Parameter(Mandatory)][string]$PlanCsv,[Parameter(Mandatory)][string]$StateDir)
$ErrorActionPreference='Stop';$resultLog=Join-Path $StateDir 'results.jsonl';if(-not(Test-Path $resultLog)){throw 'Missing results.jsonl'};$rollback=Join-Path $StateDir 'rollback';$staging=Join-Path $rollback 'staging';New-Item -ItemType Directory -Path $staging -Force|Out-Null;$rollbackLog=Join-Path $rollback 'results.jsonl'
$results=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::OrdinalIgnoreCase);foreach($line in [IO.File]::ReadLines($resultLog)){if($line){$r=$line|ConvertFrom-Json;$results[[string]$r.source]=$r}};$done=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);if(Test-Path $rollbackLog){foreach($line in [IO.File]::ReadLines($rollbackLog)){if($line){$r=$line|ConvertFrom-Json;$done.Add([string]$r.source)|Out-Null}}}
$rows=@(Import-Csv $PlanCsv);foreach($r in $rows){$s=[IO.Path]::GetFullPath($r.SourcePath);if($done.Contains($s)){continue};$terminal=$results[$s];if($terminal.status-eq'already-in-place'){continue};if(Test-Path -LiteralPath $s){throw "Original path occupied; refusing overwrite: $s"};if(-not(Test-Path -LiteralPath ([string]$terminal.final)-PathType Leaf)){throw "Terminal file missing: $($terminal.final)"};if([IO.FileInfo]::new([string]$terminal.final).Length-ne[long]$r.SizeBytes){throw "Terminal size drift: $($terminal.final)"}}
$staged=@{};for($i=0;$i-lt$rows.Count;$i++){$r=$rows[$i];$s=[IO.Path]::GetFullPath($r.SourcePath);if($done.Contains($s)){continue};$terminal=$results[$s];if($terminal.status-eq'already-in-place'){Add-Content $rollbackLog (($([ordered]@{source=$s;status='retained';final=$s;bytes=[long]$r.SizeBytes;time=(Get-Date).ToString('o')})|ConvertTo-Json -Compress));$done.Add($s)|Out-Null;continue};$sp=Join-Path $staging (('{0:D8}'-f$i)+[IO.Path]::GetExtension($s));[IO.File]::Move([string]$terminal.final,$sp);$staged[$s]=$sp}
foreach($r in $rows){$s=[IO.Path]::GetFullPath($r.SourcePath);if($done.Contains($s)){continue};New-Item -ItemType Directory -Path (Split-Path -Parent $s)-Force|Out-Null;[IO.File]::Move([string]$staged[$s],$s);Add-Content $rollbackLog (($([ordered]@{source=$s;status='restored';final=$s;bytes=[long]$r.SizeBytes;time=(Get-Date).ToString('o')})|ConvertTo-Json -Compress));$done.Add($s)|Out-Null}
[ordered]@{status='complete';restored=$done.Count;total=$rows.Count;rollbackLog=$rollbackLog}|ConvertTo-Json
